specimens.css:
/* 状态模拟：:hover 与 :focus-visible 无法静态触发，这里把 DatePicker.module.css 里 .cell:hover / .cell:focus-visible / .nav:hover 的规则原样搬到 .forceHover / .forceFocus 上；面板仍按上面的静态快照拉回文档流。 */
.panel.snapshotStatic { position: relative; inset: auto; }
.cell.forceHover { background: var(--dsw-alias-interactive-bg-hover); }
.cell.forceFocus { outline: 2px solid var(--dsw-focus-ring-color, var(--dsw-alias-state-business-primary)); outline-offset: -2px; }
.nav.forceHover { background: var(--dsw-alias-interactive-bg-hover); }
